import{_ as o,o as s,c as t,a3 as d}from"./chunks/framework.bRFWnpi3.js";const m=JSON.parse('{"title":"USB protocol","description":"","frontmatter":{},"headers":[],"relativePath":"developers/protocol.md","filePath":"developers/protocol.md"}'),a={name:"developers/protocol.md"};function c(i,e,n,r,l,h){return s(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="usb-protocol" tabindex="-1">USB protocol <a class="header-anchor" href="#usb-protocol" aria-label="Permalink to &quot;USB protocol&quot;">​</a></h1><p>s32 is the supported client for the S32 Editor USB interface. This page is the public contract overview: vendor interface, session, discovery, and command groups. You do not need firmware sources to use s32.</p><h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><p>The S32 exposes a vendor USB interface (bulk endpoints <code>0x05</code> / <code>0x85</code>, VID <code>0483</code>, PID <code>A56E</code>). That interface is <strong>exclusive</strong>: close the web editor before <code>s32 --usb</code>.</p><p>There is no password on this interface. Whoever claims it can inspect and change the live project. This is not a network service.</p><p>Protocol version is <strong>1</strong>. <code>hello</code> reports it. A mismatch fails the session instead of misparsing frames.</p><p>CLI version (<code>s32 --version</code>) is independent of the firmware patch on the device.</p><h2 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h2><ol><li>Claim the vendor interface.</li><li>Send <code>hello</code>. Confirm <code>protocolVersion</code> is 1.</li><li>Issue commands. Each request has a CRC-protected frame; the device replies with status plus an optional payload.</li><li>Subscribe to events if you need live updates (<code>watch</code> in the CLI).</li></ol><p>If a command is not available on the connected firmware, s32 prints the status the device returned (<code>Forbidden</code> for panel-only view commands, <code>TooMany</code> if mutating commands are issued faster than the device will accept).</p><p>Panel-only actions stay on the device. Library commands such as <code>project delete</code>, <code>device add</code>, <code>device remove</code>, <code>rack clear</code>, and <code>push</code> remain; s32 still prompts unless <code>--yes</code> is passed. <code>view nav</code> is hub-only (<code>perform</code>, <code>main</code>, <code>racks</code>, …) and teleports without pushing the panel Back stack.</p><h2 id="discovering-the-device" tabindex="-1">Discovering the device <a class="header-anchor" href="#discovering-the-device" aria-label="Permalink to &quot;Discovering the device&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-schema-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> layout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-layout-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> layout.json</span></span></code></pre></div><p><code>schema</code> lists device types, parameter names, and enum tables (including macro modes and menus). <code>layout</code> describes the on-disk project record for tools that decode <code>.s32p</code> files.</p><h2 id="command-groups" tabindex="-1">Command groups <a class="header-anchor" href="#command-groups" aria-label="Permalink to &quot;Command groups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>CLI</th></tr></thead><tbody><tr><td>Session</td><td><code>hello</code>, <code>ping</code>, <code>reset</code>, <code>job</code>, <code>schema</code></td></tr><tr><td>Projects</td><td><code>list</code>, <code>pull</code>, <code>push</code>, <code>project …</code></td></tr><tr><td>Macros</td><td><code>macro</code>, <code>potname</code>, <code>knobmap</code></td></tr><tr><td>LFOs</td><td><code>lfo cfg</code>, <code>lfo assign</code></td></tr><tr><td>Racks</td><td><code>rack</code>, <code>device</code>, <code>stepseq</code></td></tr><tr><td>Maps</td><td><code>extmap</code>, <code>meta</code>, <code>globals</code></td></tr><tr><td>UI</td><td><code>view</code>, <code>screen</code>, <code>watch</code></td></tr></tbody></table><p>Named tokens (<code>mode=cc</code>, <code>clockMode=internal</code>, <code>view nav racks</code>, <code>view nav s32-lfo index=5</code>) are CLI sugar. On the wire, values are the integers in the schema enum tables. <code>index=</code> is the visible list row, not the LFO number.</p>`,17)])])}const u=o(a,[["render",c]]);export{m as __pageData,u as default};
